using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
// Read-only survey: no scene edits, temporary objects, saves or Play-mode changes.
public static class B5WayfindingSurvey {
 static Transform root;static Vector3 P(JToken t)=>new Vector3((float)t[0],-82,-(float)t[1]);
 static string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;
 static bool Free(Vector3 p,float radius){return !Physics.OverlapCapsule(p+Vector3.up*.36f,p+Vector3.up*1.50f,radius,~0,QueryTriggerInteraction.Ignore).Any(c=>c.enabled&&c.transform.IsChildOf(root)&&!c.name.Contains("Floor")&&!c.name.Contains("Threshold"));}
 static bool Floor(Vector3 p){return Physics.RaycastAll(p+Vector3.up*.30f,Vector3.down,.65f,~0,QueryTriggerInteraction.Ignore).Any(h=>h.normal.y>.8f&&h.collider.transform.IsChildOf(root));}
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("B5 edit scene required");bool dirty=s.isDirty;string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var data=JObject.Parse(File.ReadAllText(repo+"/Docs/도면/Decision/원형공동/facility_layout.json"));var floor=data["floors"].Single(f=>(string)f["id"]=="B5");Physics.SyncTransforms();var corridors=new List<object>();
 foreach(var t in floor["tunnels"]){var a=P(t["p"]);var b=P(t["q"]);var dir=(b-a).normalized;var right=Vector3.Cross(Vector3.up,dir);var lanes=new List<object>();int n=Mathf.CeilToInt(Vector3.Distance(a,b)/.35f);foreach(float offset in new[]{-.66f,-.33f,0f,.33f,.66f}){var blocked=new List<int>();var unsupported=new List<int>();for(int i=0;i<=n;i++){var p=Vector3.Lerp(a,b,(float)i/n)+right*offset;if(!Free(p,.22f))blocked.Add(i);if(!Floor(p))unsupported.Add(i);}lanes.Add(new{offset,samples=n+1,blocked,unsupported});}corridors.Add(new{id=(string)t["id"],lanes});}
 var rooms=new List<object>();foreach(var r in floor["rooms"]){float x=(float)r["x"],z=-(float)r["v"],radius=(float)r["r"];const float step=.30f;int n=Mathf.CeilToInt(radius*2/step)+1;float x0=x-radius,z0=z-radius;var rows=new List<string>();for(int j=0;j<n;j++){var row=new char[n];for(int i=0;i<n;i++){var p=new Vector3(x0+i*step,-82,z0+j*step);row[i]=Vector2.Distance(new Vector2(p.x,p.z),new Vector2(x,z))>radius-.25f?'x':(Floor(p)&&Free(p,.22f)?'.':'#');}rows.Add(new string(row));}rooms.Add(new{id=(string)r["id"],x0,z0,step,rows});}
 var bounds=root.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.bounds.max.y>-81.85f&&r.bounds.min.y<-80.3f).Select(r=>new{path=PathOf(r.transform),min=new[]{r.bounds.min.x,r.bounds.min.z},max=new[]{r.bounds.max.x,r.bounds.max.z}}).ToArray();
 var result=new{scene=s.path,dirtyBefore=dirty,dirtyAfter=s.isDirty,sceneFileHash=System.Convert.ToBase64String(System.Security.Cryptography.SHA256.Create().ComputeHash(File.ReadAllBytes(Path.Combine(Application.dataPath,"..",s.path)))),coordinate="World X/Z, floor Y=-82; grid '.' has floor and a clear radius-0.22m capsule",corridors,rooms,renderBounds=bounds};string output=repo+"/SourceAssets/B5_WayfindingNetwork/survey.json";File.WriteAllText(output,JsonConvert.SerializeObject(result,Formatting.Indented));return new{corridors=corridors.Count,rooms=rooms.Count,dirtyBefore=dirty,dirtyAfter=s.isDirty,output};}
}
